// AUTO-GENERATED by scripts/build-r-helpers.ts from rhelpers/*.R.
// Do not edit. Edit the .R sources and run `pnpm gen:rhelpers`.

/**
 * The inline R helper definitions the exporter can emit, keyed by the name a
 * mark requests one by. A script carries only the helpers it references, so a
 * reader gets plain rtracklayer and ggplot2 they can edit in place.
 */
export const HELPERS: Record<string, string> = {
  alignments_fields: "# Add the read dimensions an alignments display colors and facets by, over a\n# read_bam frame: firstOfPairStrand (a second mate's strand flipped), mapq (NA\n# for unavailable), pairOrientation (LR, RL, RR or LL, \"\" for a read with\n# none), insertSize (short, normal or long against the band below), and mate,\n# which names the reads every mate-aware coloring paints alike: unmappedMate,\n# then interchrom, else NA.\n#\n# The insert-size band is JBrowse's: median +/- 3 * 1.4826 * MAD of |TLEN| over\n# primary proper pairs (mean +/- 3 sd where the MAD is 0), widened to at least\n# 2x and at most 0.5x its centre. A band with no width colors nothing, and\n# |TLEN| 0 is never short. 'cuts', the display's two insert-size cut points,\n# replace the band.\nalignments_fields <- function(reads, cuts = NULL) {\n  bit <- function(f) bitwAnd(reads$flags, f) != 0\n  reads$firstOfPairStrand <- ifelse(bit(0x80L), -reads$strand, reads$strand)\n  reads$mapq <- reads$score\n  lr <- c(F1R2 = \"LR\", F2R1 = \"LR\", R1F2 = \"RL\", R2F1 = \"RL\",\n          R1R2 = \"RR\", R2R1 = \"RR\", F1F2 = \"LL\", F2F1 = \"LL\")\n  po <- unname(lr[reads$pair_orientation])\n  reads$pairOrientation <- ifelse(is.na(po), \"\", po)\n  tlen <- abs(reads$template_length)\n  sample <- tlen[bit(0x2L) & !bit(0x100L) & !bit(0x800L) & tlen > 0]\n  band <- NULL\n  if (length(sample)) {\n    med <- median(sample); mad <- median(abs(sample - med))\n    center <- if (mad > 0) med else mean(sample)\n    spread <- 3 * (if (mad > 0) 1.4826 * mad else sqrt(mean((sample - center)^2)))\n    upper <- center + spread; lower <- max(0, center - spread)\n    if (upper > lower) {\n      mid <- (upper + lower) / 2\n      band <- c(lower = max(0, min(lower, mid * 0.5)), upper = max(upper, mid * 2))\n    }\n  }\n  if (!is.null(cuts)) band <- c(lower = min(cuts), upper = max(cuts))\n  reads$insertSize <- if (is.null(band)) rep(\"normal\", nrow(reads)) else\n    ifelse(tlen > band[[\"upper\"]], \"long\",\n      ifelse(tlen > 0 & tlen < band[[\"lower\"]], \"short\", \"normal\"))\n  interchrom <- bit(0x1L) & !is.na(reads$next_ref) & reads$next_ref != reads$refName\n  reads$mate <- ifelse(bit(0x1L) & bit(0x8L), \"unmappedMate\",\n    ifelse(interchrom, \"interchrom\", NA_character_))\n  reads\n}",
  bam_coverage: "# Read depth over a region as runs, data.frame(start, end, depth), 0-based\n# half-open, from the reads whose readGAlignments position is in 'keep' (every\n# read where NULL), so the band counts the reads the pileup under it draws.\n# Deletions and skips are carved out of the depth, as JBrowse's coverage sweep\n# carves them, and zero-depth runs are dropped.\nbam_coverage <- function(uri, chrom, start, end, keep = NULL, index = uri) {\n  bf <- BamFile(uri, index = index)\n  if (!chrom %in% seqlevels(bf)) {\n    return(data.frame(start = integer(0), end = integer(0), depth = integer(0)))\n  }\n  ga <- readGAlignments(bf, param = ScanBamParam(\n    which = GRanges(chrom, IRanges(start + 1, end))))\n  if (!is.null(keep)) ga <- ga[keep]\n  cov <- coverage(grglist(ga, drop.D.ranges = TRUE))[[chrom]]\n  ends <- cumsum(runLength(cov))\n  runs <- data.frame(start = c(0L, head(ends, -1L)), end = ends,\n                     depth = as.integer(runValue(cov)))\n  runs <- runs[runs$depth > 0 & runs$end > start & runs$start < end, ]\n  runs$start <- pmax(runs$start, start); runs$end <- pmin(runs$end, end)\n  runs\n}",
  bam_mismatches: "# Per-read mismatches, data.frame(read_index, refpos, base), refpos 0-based and\n# read_index the read's position in readGAlignments order, as read_bam numbers\n# it. Read off the MD tag where a read carries one and, as BamAdapter does,\n# against 'ref' (an indexed FASTA or 2bit) where it does not; with no 'ref' an\n# MD-less read contributes nothing.\nbam_mismatches <- function(uri, chrom, start, end, ref = NULL, index = uri) {\n  bf <- BamFile(uri, index = index)\n  if (!chrom %in% seqlevels(bf)) {\n    return(data.frame(read_index = integer(0), refpos = integer(0),\n                      base = character(0)))\n  }\n  ga <- readGAlignments(bf, param = ScanBamParam(\n    which = GRanges(chrom, IRanges(start + 1, end)), what = \"seq\", tag = \"MD\"))\n  md <- as.character(mcols(ga)$MD)\n  seqs <- as.character(mcols(ga)$seq)\n  cig <- cigar(ga); refstart <- start(ga)\n  has_md <- !is.na(md)\n  refseq <- NULL; refoff <- 0L; proj <- NULL\n  if (any(!has_md) && !is.null(ref) && nzchar(ref)) {\n    span <- GRanges(chrom, IRanges(min(refstart[!has_md]), max(end(ga)[!has_md])))\n    refseq <- getSeq(open_reference(ref), span)[[1]]\n    refoff <- start(span)\n    proj <- sequenceLayer(mcols(ga)$seq, cig, to = \"reference\")\n  }\n  out <- vector(\"list\", length(ga))\n  for (i in seq_along(ga)) {\n    if (has_md[i]) {\n      if (!grepl(\"[ACGTNacgtn]\", md[i])) next\n      ops <- regmatches(cig[i], gregexpr(\"[0-9]+[MIDNSHP=X]\", cig[i]))[[1]]\n      oplen <- as.integer(sub(\"[MIDNSHP=X]$\", \"\", ops))\n      opchr <- sub(\"^[0-9]+\", \"\", ops)\n      rp <- refstart[i]; qp <- 1L; ref_cols <- integer(0); read_cols <- integer(0)\n      for (k in seq_along(ops)) {\n        L <- oplen[k]; op <- opchr[k]\n        if (op %in% c(\"M\", \"=\", \"X\")) {\n          ref_cols <- c(ref_cols, rp:(rp + L - 1L))\n          read_cols <- c(read_cols, qp:(qp + L - 1L)); rp <- rp + L; qp <- qp + L\n        } else if (op %in% c(\"I\", \"S\")) { qp <- qp + L\n        } else if (op %in% c(\"D\", \"N\")) { rp <- rp + L }\n      }\n      toks <- regmatches(md[i], gregexpr(\"[0-9]+|\\\\^[A-Za-z]+|[A-Za-z]\", md[i]))[[1]]\n      mi <- 0L; pos <- integer(0); base <- character(0)\n      for (t in toks) {\n        if (grepl(\"^[0-9]+$\", t)) { mi <- mi + as.integer(t)\n        } else if (!startsWith(t, \"^\")) {\n          mi <- mi + 1L; pos <- c(pos, ref_cols[mi])\n          base <- c(base, substr(seqs[i], read_cols[mi], read_cols[mi]))\n        }\n      }\n      if (length(pos)) out[[i]] <- data.frame(read_index = i, refpos = pos - 1L, base = base)\n    } else if (!is.null(proj)) {\n      q <- strsplit(as.character(proj[[i]]), \"\")[[1]]\n      r <- strsplit(as.character(subseq(\n        refseq, refstart[i] - refoff + 1L, width = length(q))), \"\")[[1]]\n      d <- which(q != r & q != \"-\")\n      if (length(d)) out[[i]] <- data.frame(\n        read_index = i, refpos = refstart[i] + d - 2L, base = toupper(q[d]))\n    }\n  }\n  bind_groups(out, c(\"read_index\", \"refpos\", \"base\"))\n}",
  bed_features: "# read_bed()'s records in read_gff()'s shape (start, end, strand, type, id,\n# parent, name), so the gene glyph draws either. A BED12 record becomes an\n# mRNA with an exon per block and a CDS per block's stretch inside the thick\n# range; any other record is one 'feature'. Columns past the shared ones ride\n# on the record's own row.\n#\n# 'aggregate' names the column a BigBed groups records by, as the browser\n# does: records sharing a value, other than \"\" or \"none\", that overlap become\n# transcripts of one gene named by it; ones that do not overlap get a gene each.\nbed_features <- function(b, aggregate = NULL) {\n  if (!nrow(b)) return(cbind(b, type = character(0), id = character(0),\n    parent = character(0)))\n  b$id <- paste0(\"bed\", seq_len(nrow(b)))\n  b$parent <- NA_character_\n  b$type <- ifelse(is.na(b$block_starts), \"feature\", \"mRNA\")\n  kids <- lapply(which(!is.na(b$block_starts)), function(i) {\n    s <- b$start[i] + as.integer(strsplit(b$block_starts[i], \",\")[[1]])\n    e <- s + as.integer(strsplit(b$block_sizes[i], \",\")[[1]])\n    exon <- data.frame(start = s, end = e, type = \"exon\")\n    lo <- pmax(s, b$thick_start[i]); hi <- pmin(e, b$thick_end[i])\n    keep <- !is.na(lo) & hi > lo\n    out <- rbind(exon, data.frame(start = lo[keep], end = hi[keep],\n      type = rep(\"CDS\", sum(keep))))\n    row <- b[rep(i, nrow(out)), , drop = FALSE]\n    row$start <- out$start; row$end <- out$end; row$type <- out$type\n    row$parent <- b$id[i]; row$name <- NA_character_\n    row$id <- paste0(b$id[i], \".\", seq_len(nrow(out)))\n    row\n  })\n  key <- if (is.null(aggregate) || is.null(b[[aggregate]])) rep(NA, nrow(b)) else\n    as.character(b[[aggregate]])\n  key[key %in% c(\"\", \"none\")] <- NA\n  genes <- lapply(split(seq_len(nrow(b)), key), function(i) {\n    i <- i[order(b$start[i])]\n    overlap <- length(i) > 1 && any(b$start[i][-1] < cummax(b$end[i])[-length(i)])\n    groups <- if (overlap) list(i) else as.list(i)\n    lapply(groups, function(g) {\n      gene <- b[g[1], , drop = FALSE]\n      gene$id <- paste0(b$id[g[1]], \".gene\"); gene$parent <- NA_character_\n      gene$type <- \"gene\"; gene$name <- key[g[1]]\n      gene$start <- min(b$start[g]); gene$end <- max(b$end[g])\n      s <- b$strand[g][b$strand[g] != 0]\n      gene$strand <- if (length(s)) s[1] else 1L\n      b$parent[g] <<- gene$id\n      gene\n    })\n  })\n  out <- do.call(rbind, c(unlist(genes, recursive = FALSE), list(b), kids))\n  rownames(out) <- NULL\n  out\n}",
  bind_groups: "# rbind the frames a split produced, or a frame with 'columns' and no rows where\n# it produced none: do.call(rbind, list()) is NULL, and a NULL frame fails every\n# step and layer after it, where an empty window is a state the browser draws\n# as an empty panel.\nbind_groups <- function(parts, columns) {\n  out <- do.call(rbind, parts)\n  if (is.null(out)) {\n    out <- data.frame(setNames(rep(list(logical(0)), length(columns)), columns),\n                      check.names = FALSE)\n  }\n  out\n}",
  category_values: "# The palette entry each categorical value takes, by the browser's rule: a\n# non-negative integer takes the slot it names anchored at 1, anything else\n# hashes in (hashString: 31 * h + code unit, as a signed 32-bit integer). A\n# value in 'listed' (a named vector) keeps the entry listed for it. Answers a\n# vector named by value, for scale_*_manual(values = ).\ncategory_values <- function(values, palette, listed = NULL) {\n  hash <- function(s) {\n    h <- 0\n    for (ch in utf8ToInt(s)) h <- (h * 31 + ch) %% 4294967296\n    abs(if (h >= 2147483648) h - 4294967296 else h)\n  }\n  slot <- function(v) {\n    num <- if (nzchar(v) && !nzchar(trimws(v))) 0 else suppressWarnings(as.numeric(v))\n    if (nzchar(v) && is.finite(num) && num == floor(num) && num >= 0)\n      (num + length(palette) - 1) %% length(palette)\n    else hash(v) %% length(palette)\n  }\n  values <- unique(as.character(values[!is.na(values)]))\n  out <- palette[vapply(values, slot, numeric(1)) + 1]\n  names(out) <- values\n  c(listed, out[setdiff(values, names(listed))])\n}",
  clip_regions: "# Cut each row's start and end to the region its '.region' names, on the\n# cumulative axis, dropping what falls wholly outside: a glyph laid out whole\n# would otherwise draw over the gap into the next region.\nclip_regions <- function(d, regions) {\n  lo <- regions$cum_start[d$.region]; hi <- regions$cum_end[d$.region]\n  d$start <- pmax(d$start, lo); d$end <- pmin(d$end, hi)\n  d[d$end > d$start, , drop = FALSE]\n}",
  collapse_isoforms: "# Keep one transcript per gene, as the display's representative-transcript\n# glyph mode does. Ranked as the browser ranks isoforms: a curated tag in\n# 'canonical_tags' (by its position, held in the 'canonical_field' attribute,\n# which read_gff must have been asked for), then coding over non-coding, then the\n# longest protein (summed CDS bp, deduplicated) or widest span, a tie going to\n# the later isoform. 'transcript_types' names the child types counted as\n# isoforms; a gene with none treats its direct children as the isoforms.\ncollapse_isoforms <- function(f, transcript_types, canonical_field = NULL,\n                              canonical_tags = character(0)) {\n  if (is.null(f) || !nrow(f)) return(f)\n  fid <- ifelse(is.na(f$id), paste0(\"_f\", seq_len(nrow(f))), f$id)\n  by_parent <- split(seq_len(nrow(f)), f$parent)   # drops the parent-less roots\n  descendants <- function(id) {\n    out <- integer(0); stack <- id\n    while (length(stack)) {\n      kids <- by_parent[[stack[1]]]; stack <- stack[-1]\n      if (!is.null(kids)) { out <- c(out, kids); stack <- c(stack, fid[kids]) }\n    }\n    out\n  }\n  coding_bp <- function(idx) {\n    cds <- idx[tolower(f$type[idx]) == \"cds\"]\n    if (!length(cds)) return(0)\n    keep <- !duplicated(paste(f$start[cds], f$end[cds]))\n    sum(f$end[cds][keep] - f$start[cds][keep])\n  }\n  wanted <- tolower(canonical_tags)\n  tags <- if (length(wanted) && !is.null(canonical_field)) f[[canonical_field]] else NULL\n  canonical_rank <- function(idx) vapply(idx, function(i) {\n    v <- tags[i]\n    if (is.na(v)) return(Inf)\n    hit <- match(tolower(trimws(strsplit(v, \",\", fixed = TRUE)[[1]])), wanted)\n    if (all(is.na(hit))) Inf else min(hit, na.rm = TRUE)\n  }, numeric(1))\n  tt <- tolower(transcript_types)\n  drop <- integer(0)\n  for (root in fid[is.na(f$parent)]) {\n    kids <- by_parent[[root]]\n    if (is.null(kids) || length(kids) < 2 || !any(fid[kids] %in% f$parent)) next\n    iso <- kids[tolower(f$type[kids]) %in% tt]\n    if (!length(iso)) iso <- kids\n    if (length(iso) < 2) next\n    subtrees <- lapply(iso, function(i) c(i, descendants(fid[i])))\n    coding <- vapply(subtrees, coding_bp, numeric(1))\n    size <- ifelse(coding > 0, coding, f$end[iso] - f$start[iso])\n    rank <- if (is.null(tags)) rep(Inf, length(iso)) else canonical_rank(iso)\n    winner <- order(rank, -(coding > 0), -size, -seq_along(iso))[1]\n    drop <- c(drop, unlist(subtrees[-winner]))\n  }\n  if (length(drop)) f[-drop, , drop = FALSE] else f\n}",
  feature_filter: "# The track's admission gate: the top-level features every predicate in 'preds'\n# passes, each with its whole subtree, as JBrowse admits them. A predicate takes\n# the frame and returns one logical per row, so a filter is ordinary R to edit\n# or add to (`function(f) f$type != \"match\"`). A child of a dropped feature\n# stays in the frame and draws nowhere, since gene_layout() lays out from the\n# top-level features.\nfeature_filter <- function(f, preds = list()) {\n  pass <- Reduce(`&`, lapply(preds, function(p) p(f)), rep(TRUE, nrow(f)))\n  f[!is.na(f$parent) | pass, , drop = FALSE]\n}",
  file_refname: "# The name a file spells a contig with, where the assembly's alias for it\n# differs from the view's name; a contig with no alias keeps its own name.\nfile_refname <- function(chrom, aliases) {\n  if (chrom %in% names(aliases)) aliases[[chrom]] else chrom\n}",
  gene_layout: "# One row per lane the feature glyph draws, packed into rows. A top-level\n# feature whose children carry parts of their own (gene -> mRNA -> CDS) stacks\n# one lane per child; any other is one lane. Rows come from\n# IRanges::disjointBins over each feature plus the text under it, which the\n# browser reserves too, so names never collide; a row is as tall as its\n# tallest feature. 'char_bp' is one character's width in bp. 'y' is a lane's\n# centre in feature heights counting down from 0, 'bottom' its row's lower\n# edge, and 'label' and 'description' are set on a feature's last lane only.\ngene_layout <- function(f, char_bp = 0, labels = f$name,\n                        descriptions = rep(NA_character_, nrow(f)),\n                        pitch = 1.2, line_h = 1.2, gap = 0.5) {\n  fid <- ifelse(is.na(f$id), paste0(\"_f\", seq_len(nrow(f))), f$id)\n  up <- match(f$parent, fid)\n  roots <- which(is.na(f$parent))\n  stacking <- intersect(up[!is.na(up) & seq_len(nrow(f)) %in% up], roots)\n  lanes <- c(setdiff(roots, stacking), which(up %in% stacking))\n  gene <- ifelse(lanes %in% roots, lanes, up[lanes])\n  lanes <- lanes[order(gene, lanes)]\n  gene <- sort(gene)\n  out <- f[lanes, , drop = FALSE]\n  out$id <- fid[lanes]\n  out$gene <- fid[gene]\n  out$lane <- ave(seq_along(lanes), gene, FUN = seq_along) - 1L\n  depth <- ave(out$lane, gene, FUN = max) + 1L\n  label <- labels[gene]\n  desc <- descriptions[gene]\n  width <- function(s) ifelse(is.na(s), 0, nchar(s))\n  chars <- pmax(width(label), width(desc))\n  lines <- (!is.na(label)) + (!is.na(desc))\n  h <- depth * pitch + lines * line_h + gap\n  first <- out$lane == 0\n  bin <- integer(nrow(out))\n  bin[first] <- disjointBins(IRanges(f$start[gene][first] + 1,\n    pmax(f$end[gene][first], f$start[gene][first] + chars[first] * char_bp)))\n  bin <- ave(bin, gene, FUN = max)\n  band <- tapply(h, bin, max)\n  at <- match(bin, as.integer(names(band)))\n  top <- c(0, cumsum(band))[at]\n  out$y <- top + out$lane * pitch + 0.5\n  last <- out$lane == depth - 1L\n  out$label <- ifelse(last, label, NA_character_)\n  out$description <- ifelse(last, desc, NA_character_)\n  out$description_y <- out$y + 0.6 + ifelse(is.na(out$label), 0, line_h)\n  out$bottom <- top + band[at]\n  rownames(out) <- NULL\n  out\n}",
  gene_parts: "# The boxes each lane of gene_layout() draws, one row per box: start, end, y\n# and 'part', which is \"CDS\", \"UTR\" (drawn thinner) or \"box\". A lane with a CDS\n# child draws the children whose type 'sub_parts' names, plus, with\n# 'implied_utrs', the untranslated ends its exons (or, lacking exons, its own\n# bounds) reach past the outermost CDS on a side no UTR row covers. A lane with\n# other children draws them all; a lane with none is one box.\ngene_parts <- function(f, lanes, sub_parts = c(\"CDS\", \"UTR\", \"five_prime_UTR\",\n                       \"three_prime_UTR\"), implied_utrs = TRUE) {\n  utr <- function(type) grepl(\"(\\\\bUTR|_UTR|untranslated[_ ]region)\\\\b\", type,\n                              ignore.case = TRUE, perl = TRUE)\n  kids <- split(f, factor(f$parent, levels = unique(lanes$id)))\n  parts <- lapply(seq_len(nrow(lanes)), function(i) {\n    l <- lanes[i, ]\n    k <- kids[[l$id]]\n    box <- function(s, e, part) if (length(s)) data.frame(start = s, end = e,\n      part = part, lane = l$id, y = l$y, .region = l$.region,\n      stringsAsFactors = FALSE, check.names = FALSE)\n    if (is.null(k) || !nrow(k)) {\n      return(box(l$start, l$end, if (tolower(l$type) == \"cds\") \"CDS\" else \"box\"))\n    }\n    cds <- tolower(k$type) == \"cds\"\n    if (!any(cds)) return(box(k$start, k$end, \"box\"))\n    lo <- min(k$start[cds]); hi <- max(k$end[cds])\n    shown <- k[tolower(k$type) %in% tolower(sub_parts), , drop = FALSE]\n    out <- list(box(shown$start, shown$end, ifelse(utr(shown$type), \"UTR\", \"CDS\")))\n    if (implied_utrs) {\n      u <- utr(k$type)\n      ex <- k[tolower(k$type) == \"exon\", , drop = FALSE]\n      if (!nrow(ex)) ex <- l\n      if (!any(k$start[u] < lo)) {\n        s <- ex$start < lo\n        out <- c(out, list(box(ex$start[s], pmin(ex$end[s], lo), \"UTR\")))\n      }\n      if (!any(k$end[u] > hi)) {\n        s <- ex$end > hi\n        out <- c(out, list(box(pmax(ex$start[s], hi), ex$end[s], \"UTR\")))\n      }\n    }\n    do.call(rbind, out)\n  })\n  out <- do.call(rbind, parts)\n  if (is.null(out)) out <- data.frame(start = numeric(0), end = numeric(0),\n    part = character(0), lane = character(0), y = numeric(0),\n    .region = integer(0), check.names = FALSE)\n  out\n}",
  open_reference: "# A reference sequence handle for whichever format the assembly stores it in.\n# Both answer getSeq(handle, GRanges) the same way, so callers need not care.\n# An indexed FASTA wants its .fai beside it; a 2bit carries its own index.\nopen_reference <- function(path) {\n  if (grepl(\"\\\\.2bit$\", path, ignore.case = TRUE)) {\n    rtracklayer::TwoBitFile(path)\n  } else {\n    FaFile(path)\n  }\n}",
  read_bam: "# Read the alignments overlapping a region into data.frame(start, end, strand,\n# name, score, flags, template_length, pair_orientation, next_ref, next_pos,\n# refName, read_index), the fields a JBrowse read answers to under the same\n# names, plus each read's position in readGAlignments order, which a per-read\n# overlay such as bam_mismatches joins on: start is 0-based\n# half-open over the reference span the CIGAR covers, strand is 1 or -1, score\n# is MAPQ with 255 (unavailable) as NA, template_length is signed TLEN, and\n# pair_orientation is the F1R2-style code, NA unless both mates map to one\n# contig. One tags.<TAG> column per name in 'tags', numeric where every value\n# parses as a number. Unmapped reads are not returned, and a contig the index\n# lacks reads as no reads.\nread_bam <- function(uri, chrom, start, end, tags = character(0), index = uri) {\n  bf <- BamFile(uri, index = index)\n  known <- chrom %in% seqlevels(bf)\n  which <- if (known) GRanges(chrom, IRanges(start + 1, end))\n    else GRanges(seqlevels(bf)[1], IRanges(1, 1))\n  ga <- readGAlignments(bf, param = ScanBamParam(which = which, tag = tags,\n    what = c(\"qname\", \"flag\", \"mapq\", \"isize\", \"mrnm\", \"mpos\")))\n  if (!known) ga <- ga[0]\n  m <- mcols(ga)\n  flag <- m$flag\n  bit <- function(f) bitwAnd(flag, f) != 0\n  paired <- bit(0x1L)\n  mate_chrom <- as.character(m$mrnm)\n  oriented <- paired & !bit(0x4L) & !bit(0x8L) & !is.na(mate_chrom) & mate_chrom == chrom\n  self_left <- ifelse(start(ga) != m$mpos, start(ga) < m$mpos, bit(0x40L))\n  self <- paste0(ifelse(bit(0x10L), \"R\", \"F\"), ifelse(bit(0x40L), \"1\", \"2\"))\n  mate <- paste0(ifelse(bit(0x20L), \"R\", \"F\"), ifelse(bit(0x40L), \"2\", \"1\"))\n  df <- data.frame(start = start(ga) - 1L, end = end(ga),\n    strand = ifelse(as.character(strand(ga)) == \"-\", -1L, 1L),\n    name = m$qname, score = ifelse(m$mapq == 255L, NA_integer_, m$mapq),\n    flags = flag, template_length = m$isize,\n    pair_orientation = ifelse(oriented,\n      ifelse(self_left, paste0(self, mate), paste0(mate, self)), NA_character_),\n    next_ref = ifelse(paired, mate_chrom, NA_character_),\n    next_pos = ifelse(paired & !is.na(m$mpos), m$mpos - 1L, NA_integer_),\n    refName = rep(chrom, length(ga)), read_index = seq_along(ga),\n    stringsAsFactors = FALSE, check.names = FALSE)\n  for (t in tags) df[[paste0(\"tags.\", t)]] <- utils::type.convert(\n    if (is.null(m[[t]])) rep(NA_character_, length(ga)) else as.character(m[[t]]),\n    as.is = TRUE)\n  df\n}",
  read_bed: "# Read the BED records in a region through the file's tabix index into a\n# data.frame(start, end, strand, name, score, thick_start, thick_end,\n# block_starts, block_sizes), one row per record: start is 0-based half-open,\n# strand 1, -1 or 0, and the block columns are BED12's comma lists, block\n# starts relative to the record's start, NA on a record without blocks. A\n# contig the index lacks reads as no records, as the browser draws it.\nread_bed <- function(uri, chrom, start, end, index = paste0(uri, \".tbi\")) {\n  tf <- TabixFile(uri, index = index)\n  g <- if (!chrom %in% seqnamesTabix(tf)) GRanges() else\n    import(tf, which = GRanges(chrom, IRanges(start + 1, end)), format = \"bed\")\n  m <- mcols(g)\n  n <- length(g)\n  na <- rep(NA_character_, n)\n  thick <- if (is.null(m$thick)) NULL else m$thick\n  blocks <- if (is.null(m$blocks)) NULL else m$blocks\n  data.frame(\n    start = start(g) - 1L, end = end(g),\n    strand = unname(c(\"+\" = 1L, \"-\" = -1L, \"*\" = 0L)[as.character(strand(g))]),\n    name = if (is.null(m$name)) na else as.character(m$name),\n    score = if (is.null(m$score)) rep(NA_real_, n) else as.numeric(m$score),\n    thick_start = if (is.null(thick)) rep(NA_integer_, n) else start(thick) - 1L,\n    thick_end = if (is.null(thick)) rep(NA_integer_, n) else end(thick),\n    block_starts = if (is.null(blocks)) na else\n      vapply(blocks, function(b) paste(start(b) - 1L, collapse = \",\"), \"\"),\n    block_sizes = if (is.null(blocks)) na else\n      vapply(blocks, function(b) paste(width(b), collapse = \",\"), \"\"),\n    stringsAsFactors = FALSE)\n}",
  read_bigbed: "# Read the BigBed records in a region into read_bed()'s data.frame(start, end,\n# strand, name, score, thick_start, thick_end, block_starts, block_sizes), plus\n# one column per name in 'fields', the file's autoSql columns the display\n# reads, numeric where every value parses as a number. 'score_column' names\n# the column the adapter reads score from. A contig the file lacks reads as no\n# records, as the browser draws it.\n#\n# rtracklayer's BigBed reader fails on any list column, which every BED12\n# bigBed has, so this walks the file itself: the chromosome B+ tree to the\n# contig's id, the R-tree to the data blocks that overlap, then the\n# zlib-compressed records. A URL is read in HTTP ranges.\nread_bigbed <- function(uri, chrom, start, end, fields = character(0), score_column = NULL) {\n  whole <- NULL\n  fetch <- if (grepl(\"^[a-z]+://\", uri)) function(off, n) {\n    if (is.null(whole)) {\n      h <- curl::new_handle(range = sprintf(\"%.0f-%.0f\", off, off + n - 1))\n      r <- curl::curl_fetch_memory(uri, handle = h)\n      if (r$status_code == 206) return(r$content)\n      # A server that ignores the range sends the whole file once.\n      whole <<- r$content\n    }\n    whole[seq.int(off + 1, min(length(whole), off + n))]\n  } else function(off, n) {\n    con <- file(uri, \"rb\"); on.exit(close(con))\n    seek(con, off); readBin(con, \"raw\", n)\n  }\n  en <- \"little\"\n  u32 <- function(b, p) {\n    v <- readBin(b[p:(p + 3)], \"integer\", 1, 4, endian = en)\n    if (v < 0) v + 2^32 else v\n  }\n  u16 <- function(b, p) readBin(b[p:(p + 1)], \"integer\", 1, 2, signed = FALSE, endian = en)\n  u64 <- function(b, p) if (en == \"little\") u32(b, p) + u32(b, p + 4) * 2^32 else\n    u32(b, p) * 2^32 + u32(b, p + 4)\n\n  h <- fetch(0, 64)\n  if (u32(h, 1) != 0x8789F2EB) en <- \"big\"\n  if (u32(h, 1) != 0x8789F2EB) stop(uri, \" is not a BigBed file\")\n  chrom_tree <- u64(h, 9); index <- u64(h, 25)\n  defined <- u16(h, 35); sql_at <- u64(h, 37); compressed <- u32(h, 53) > 0\n\n  sql <- fetch(sql_at, 65536)\n  sql <- rawToChar(sql[seq_len(match(as.raw(0), sql, length(sql) + 1) - 1)])\n  names <- regmatches(sql, gregexpr(\"[A-Za-z_][A-Za-z0-9_]*(?=\\\\s*;)\", sql, perl = TRUE))[[1]]\n\n  # The B+ tree's keys are the names null-padded to keySize and sorted bytewise.\n  t <- fetch(chrom_tree, 32)\n  block <- u32(t, 5); key_size <- u32(t, 9)\n  target <- charToRaw(chrom)\n  cid <- if (length(target) > key_size) NA else {\n    target <- c(target, raw(key_size - length(target)))\n    le <- function(a) { d <- which(a != target)[1]; is.na(d) || a[d] < target[d] }\n    node <- chrom_tree + 32; found <- NA\n    repeat {\n      b <- fetch(node, 4 + block * (key_size + 8))\n      n <- u16(b, 3); at <- 4 + (seq_len(n) - 1) * (key_size + 8)\n      keys <- lapply(at, function(p) b[p + seq_len(key_size)])\n      if (b[1] == 1) {\n        hit <- which(vapply(keys, function(k) all(k == target), TRUE))\n        if (length(hit)) found <- u32(b, at[hit[1]] + key_size + 1)\n        break\n      }\n      below <- which(vapply(keys, le, TRUE))\n      if (!length(below)) break\n      node <- u64(b, at[max(below)] + key_size + 1)\n    }\n    found\n  }\n\n  # Overlap compares (chromIx, base) pairs, since a leaf can span contigs.\n  index_block <- u32(fetch(index, 48), 5)\n  blocks <- list()\n  walk <- function(node) {\n    b <- fetch(node, 4 + index_block * 32)\n    leaf <- b[1] == 1; n <- u16(b, 3); size <- if (leaf) 32 else 24\n    for (i in seq_len(n)) {\n      p <- 5 + (i - 1) * size\n      sc <- u32(b, p); sb <- u32(b, p + 4); ec <- u32(b, p + 8); eb <- u32(b, p + 12)\n      if ((sc < cid || (sc == cid && sb < end)) && (ec > cid || (ec == cid && eb > start))) {\n        if (leaf) blocks[[length(blocks) + 1]] <<- c(u64(b, p + 16), u64(b, p + 24))\n        else walk(u64(b, p + 16))\n      }\n    }\n  }\n  if (!is.na(cid)) walk(index + 48)\n\n  rows <- list()\n  for (bl in blocks) {\n    b <- fetch(bl[1], bl[2])\n    if (compressed) b <- memDecompress(b, \"gzip\")\n    nul <- which(b == as.raw(0)); p <- 1\n    while (p + 12 <= length(b)) {\n      z <- nul[findInterval(p + 11, nul) + 1]\n      if (is.na(z)) break\n      if (u32(b, p) == cid) {\n        s <- u32(b, p + 4); e <- u32(b, p + 8)\n        if (s < end && e > start) rows[[length(rows) + 1]] <-\n          list(s, e, if (z > p + 12) rawToChar(b[(p + 12):(z - 1)]) else \"\")\n      }\n      p <- z + 1\n    }\n  }\n\n  rest <- lapply(rows, function(r) strsplit(r[[3]], \"\\t\", fixed = TRUE)[[1]])\n  col <- function(i) vapply(rest, function(r) if (length(r) >= i) r[[i]] else NA_character_, \"\")\n  bed <- function(i, f) if (defined >= i + 3) f(col(i)) else f(rep(NA_character_, length(rows)))\n  num <- function(v) suppressWarnings(as.numeric(v))\n  list_col <- function(v) sub(\",$\", \"\", v)\n  df <- data.frame(\n    start = vapply(rows, function(r) as.integer(r[[1]]), 0L),\n    end = vapply(rows, function(r) as.integer(r[[2]]), 0L),\n    strand = bed(3, function(v) ifelse(v %in% \"+\", 1L, ifelse(v %in% \"-\", -1L, 0L))),\n    name = bed(1, identity), score = bed(2, num),\n    thick_start = bed(4, num), thick_end = bed(5, num),\n    block_starts = bed(9, list_col), block_sizes = bed(8, list_col),\n    stringsAsFactors = FALSE)\n  named <- function(f) {\n    i <- match(f, names) - 3\n    if (is.na(i) || i < 1) rep(NA_character_, nrow(df)) else col(i)\n  }\n  if (!is.null(score_column)) df$score <- num(named(score_column))\n  for (f in fields) df[[f]] <- utils::type.convert(named(f), as.is = TRUE)\n  df\n}",
  read_bigwig: "# Read a BigWig region into data.frame(seqnames, start, end, score), start\n# 0-based half-open like every reader here (rtracklayer answers 1-based\n# inclusive, which leaves a 1bp hole between adjacent bins). Opened as a\n# BigWigFile so a URL whose query hides the extension still reads.\nread_bigwig <- function(uri, chrom, start, end) {\n  gr <- rtracklayer::import(rtracklayer::BigWigFile(uri),\n                            which = GRanges(chrom, IRanges(start + 1, end)))\n  df <- as.data.frame(gr)\n  df$start <- df$start - 1L\n  df\n}",
  read_filter: "# The reads an alignments display's filterBy keeps, from a read_bam frame: every\n# flag_include bit set, no flag_exclude bit set (1540, JBrowse's default, drops\n# QC failures and duplicates), the read name where one is given, and each tag\n# filter, whose tag column read_bam must have read: \"*\" keeps a read carrying\n# the tag, any other value a read whose tag reads as it.\nread_filter <- function(reads, flag_include = 0, flag_exclude = 1540,\n                        read_name = NULL, tags = list()) {\n  keep <- bitwAnd(reads$flags, flag_include) == flag_include &\n    bitwAnd(reads$flags, flag_exclude) == 0\n  if (!is.null(read_name)) keep <- keep & reads$name %in% read_name\n  for (tag in names(tags)) {\n    v <- reads[[paste0(\"tags.\", tag)]]\n    keep <- keep & !is.na(v) & (tags[[tag]] == \"*\" | as.character(v) == tags[[tag]])\n  }\n  reads[keep, , drop = FALSE]\n}",
  read_gff: "# Read the GFF3 features in a region through the file's tabix index into a\n# data.frame(start, end, strand, type, source, score, phase, id, parent, name),\n# plus one column per name in 'attrs', the column-9 attributes the display\n# reads: matched without regard to case, as JBrowse matches them; numeric where\n# every value parses as a number, as a channel reads it; all NA where the file\n# lacks the attribute. start is 0-based half-open, and strand is 1, -1 or 0, the\n# values a config's strand domain names. A contig the index lacks reads as no\n# features, as the browser draws it.\nread_gff <- function(uri, chrom, start, end, attrs = character(0), index = paste0(uri, \".tbi\")) {\n  tf <- TabixFile(uri, index = index)\n  g <- if (!chrom %in% seqnamesTabix(tf)) GRanges() else withCallingHandlers(\n    import(tf, which = GRanges(chrom, IRanges(start + 1, end)), format = \"gff3\"),\n    # rtracklayer rewinds the connection it opened itself and warns about it\n    warning = function(w) if (grepl(\"rewinding\", conditionMessage(w))) invokeRestart(\"muffleWarning\"))\n  m <- mcols(g)\n  # A GFF attribute can hold a comma list, which rtracklayer surfaces as a\n  # CharacterList - and as.character() on one errors rather than flattening, so\n  # join it back to the spelling the file used.\n  col <- function(nm) {\n    hit <- match(tolower(nm), tolower(names(m)))\n    v <- if (is.na(hit)) NULL else m[[hit]]\n    if (is.null(v)) rep(NA_character_, length(g))\n    else if (methods::is(v, \"List\")) vapply(v, function(x)\n      if (length(x)) paste(as.character(x), collapse = \",\") else NA_character_,\n      character(1))\n    else as.character(v)\n  }\n  parent <- if (is.null(m$Parent)) rep(NA_character_, length(g)) else\n    vapply(m$Parent, function(v) if (length(v)) as.character(v[[1]]) else NA_character_, character(1))\n  df <- data.frame(start = start(g) - 1L, end = end(g), strand = unname(c(\"+\" = 1L, \"-\" = -1L, \"*\" = 0L)[as.character(strand(g))]),\n             type = col(\"type\"), source = col(\"source\"),\n             score = suppressWarnings(as.numeric(col(\"score\"))),\n             phase = suppressWarnings(as.integer(col(\"phase\"))),\n             id = col(\"ID\"), parent = parent, name = col(\"Name\"),\n             stringsAsFactors = FALSE, check.names = FALSE)\n  for (a in attrs) df[[a]] <- utils::type.convert(col(a), as.is = TRUE)\n  df\n}",
  read_regions: "# Read one data.frame per region with reader(chrom, start, end), shift the\n# columns 'coords' names onto the cumulative-bp axis region_layout() defines and\n# rbind the frames into one, with a '.region' column, so a single ggplot panel\n# spans several discontiguous regions on one x-axis. 'reader' answers a\n# genomic-coordinate data.frame, with no rows for a region holding nothing.\n# A feature is clipped to its region only where there is more than one: the\n# browser runs its transforms over the unclipped feature and clips the drawing,\n# which coord_cartesian() does for a lone region, while on a shared axis a\n# feature past its region's edge would draw over the gap into the next region.\nread_regions <- function(reader, regions, coords, clip = nrow(regions) > 1) {\n  parts <- lapply(seq_len(nrow(regions)), function(i) {\n    df <- reader(regions$chrom[i], regions$start[i], regions$end[i])\n    shift <- regions$offset[i] - regions$start[i]\n    for (col in coords) {\n      v <- df[[col]]\n      if (clip) v <- pmin(pmax(v, regions$start[i]), regions$end[i])\n      df[[col]] <- v + shift\n    }\n    df$.region <- rep(i, nrow(df))\n    df\n  })\n  do.call(rbind, parts)\n}",
  read_vcf: "# Read VCF records in a region via the tabix index (Rsamtools - no\n# VariantAnnotation needed) into data.frame(start, end, name, REF, ALT, QUAL,\n# FILTER, type), plus one INFO.<key> column per key in 'info', the INFO fields\n# the display reads - a flag key is TRUE where present and NA where not, and a\n# column every value of which parses as a number becomes numeric. SV span (END)\n# comes from INFO, and type is the browser's SO term from the alleles: SNV,\n# substitution, insertion, deletion, breakend, a symbolic alt's class, joined\n# across alts.\n# start is 0-based half-open (BED-style). A contig the index lacks reads as no\n# records, as the browser draws it.\nread_vcf <- function(uri, chrom, start, end, info = character(0), index = paste0(uri, \".tbi\")) {\n  info_field <- function(inf, key) {\n    pat <- paste0(\"(?:^|;)\", key, \"(?:=([^;]*))?(?:;|$)\")\n    vapply(inf, function(x) {\n      m <- regmatches(x, regexec(pat, x, perl = TRUE))[[1]]\n      if (!length(m)) NA_character_ else if (nzchar(m[2])) m[2] else \"TRUE\"\n    }, character(1), USE.NAMES = FALSE)\n  }\n  tf <- TabixFile(uri, index = index)\n  lines <- if (!chrom %in% seqnamesTabix(tf)) character(0) else\n    unlist(scanTabix(tf, param = GRanges(chrom, IRanges(start + 1, end))))\n  cols <- if (length(lines)) do.call(rbind, strsplit(lines, \"\\t\", fixed = TRUE))\n          else matrix(character(), 0, 8)\n  pos <- as.integer(cols[, 2]); ref <- cols[, 4]\n  alt <- sub(\",.*\", \"\", cols[, 5]); inf <- cols[, 8]\n  symbolic <- grepl(\"^<\", alt)\n  end_info <- suppressWarnings(as.integer(info_field(inf, \"END\")))\n  symbolic_terms <- c(DEL = \"deletion\", INS = \"insertion\", DUP = \"duplication\",\n    INV = \"inversion\", INVDUP = \"inverted_duplication\",\n    CNV = \"copy_number_variation\", TRA = \"translocation\",\n    \"DUP:TANDEM\" = \"tandem_duplication\", NON_REF = \"sequence_variant\",\n    \"*\" = \"sequence_variant\")\n  so_term <- function(a, r) {\n    if (a == \".\") return(\"remark\")\n    if (startsWith(a, \"<\")) {\n      parts <- strsplit(substr(a, 2, nchar(a) - 1), \":\", fixed = TRUE)[[1]]\n      for (i in rev(seq_along(parts))) {\n        term <- paste(parts[seq_len(i)], collapse = \":\")\n        if (term %in% names(symbolic_terms)) return(symbolic_terms[[term]])\n        if (grepl(\"^CN[0-9]+$\", term)) return(\"copy_number_variation\")\n      }\n      return(\"variant\")\n    }\n    if (a == \"*\") return(\"sequence_variant\")\n    if (grepl(\"[][]\", a)) return(\"breakend\")\n    if (nchar(r) == 1 && nchar(a) == 1) \"SNV\"\n    else if (nchar(r) == nchar(a)) \"substitution\"\n    else if (nchar(r) < nchar(a)) \"insertion\"\n    else \"deletion\"\n  }\n  type <- as.character(unlist(Map(function(r, a) paste(unique(\n    vapply(strsplit(a, \",\", fixed = TRUE)[[1]], so_term, \"\", r = r)),\n    collapse = \",\"), ref, cols[, 5], USE.NAMES = FALSE)))\n  df <- data.frame(start = pos - 1L,\n             end = ifelse(symbolic & !is.na(end_info), end_info, pos + nchar(ref) - 1L),\n             name = ifelse(cols[, 3] == \".\", NA_character_, cols[, 3]),\n             REF = ref, ALT = alt,\n             QUAL = suppressWarnings(as.numeric(cols[, 6])),\n             FILTER = cols[, 7], type = type,\n             stringsAsFactors = FALSE, check.names = FALSE)\n  for (k in info) df[[paste0(\"INFO.\", k)]] <-\n    utils::type.convert(info_field(inf, k), as.is = TRUE)\n  df\n}",
  region_layout: "# Lay a set of displayed regions out on one continuous \"cumulative bp\" x-axis,\n# the way JBrowse concatenates several regions in a single linear view: each\n# region occupies a span proportional to its bp width, with a small gap between\n# them. 'regions' is a data.frame(chrom, start, end) (0-based half-open); this\n# adds offset (the region's left edge on the cumulative axis), width, gap, and\n# cum_start/cum_end. The first region is anchored at its own genomic start, so a\n# lone region keeps native genomic coordinates (a single-region figure is\n# unchanged). cum_pos for a position p in region i is offset[i] + (p - start[i]).\nregion_layout <- function(regions, gap_frac = 0.012) {\n  w <- regions$end - regions$start\n  gap <- max(1, round(sum(w) * gap_frac))\n  regions$offset <- regions$start[1] + head(cumsum(c(0, w + gap)), length(w))\n  regions$width <- w; regions$gap <- gap\n  regions$cum_start <- regions$offset; regions$cum_end <- regions$offset + w\n  regions\n}",
  step_path: "# The vertices of a step line through df, for geom_path(aes(.x, .y, group =\n# .group)): each row's value 'y' held from 'x' to 'x2', joined to the next row\n# where that one starts at this one's end, and dropped to 'origin' across a\n# gap, as the browser draws a line mark. The rows of one group, one value of\n# every column 'by' names, draw as one path in 'x' order. Each vertex carries\n# its row's columns, so a color mapped to one stays per span.\nstep_path <- function(df, x, x2, y, origin = 0, by = \".region\") {\n  n <- nrow(df)\n  df$.group <- if (n) interaction(lapply(df[by], addNA), drop = TRUE) else factor()\n  df <- df[order(df$.group, df[[x]]), , drop = FALSE]\n  abuts <- if (!n) logical(0) else\n    c(FALSE, df$.group[-1] == df$.group[-n] & df[[x]][-1] == df[[x2]][-n])\n  k <- rep(seq_len(n), each = 4)\n  corner <- rep(1:4, n)\n  out <- df[k, , drop = FALSE]\n  out$.x <- ifelse(corner <= 2, df[[x]][k], df[[x2]][k])\n  out$.y <- ifelse(corner == 2 | corner == 3, df[[y]][k], origin)\n  keep <- corner == 2 | corner == 3 |\n    (corner == 1 & !abuts[k]) | (corner == 4 & !c(abuts[-1], FALSE)[k])\n  out[keep, , drop = FALSE]\n}",
  whole_features: "# The features reader(chrom, start, end) finds overlapping the region, each\n# with its whole subtree: an index query answers only the rows that overlap,\n# so a transcript reaching into the region arrived without its outside exons.\n# The query is widened to the span of what it found, then cut back to the\n# features whose top-level ancestor overlaps the region, as the browser draws.\n# A frame without a 'parent' column holds whole records already.\nwhole_features <- function(reader, chrom, start, end) {\n  f <- reader(chrom, start, end)\n  if (!nrow(f) || is.null(f$parent)) return(f)\n  lo <- min(f$start); hi <- max(f$end)\n  if (lo < start || hi > end) f <- reader(chrom, lo, hi)\n  fid <- ifelse(is.na(f$id), paste0(\"_f\", seq_len(nrow(f))), f$id)\n  root <- seq_len(nrow(f))\n  for (depth in 1:64) {\n    up <- match(f$parent[root], fid)\n    step <- !is.na(up)\n    if (!any(step)) break\n    root[step] <- up[step]\n  }\n  f[f$start[root] < end & f$end[root] > start, , drop = FALSE]\n}",
}
